function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(30);
	noFill();
	stroke("silver");
	loop();
}

function draw() {
	background(32);

	const w2 = width/2;
	const h2 = height/2;
	const r1 = max(width, height) * 0.45;
	const r2 = max(width, height) * 0.1;
	const num = 33;
	for (let i = 0; i < num; i++) {
		const da = sin(map(i, 0, num-1, -PI, PI) + frameCount/12) / 8; // -QUARTER_PI, QUARTER_PI
		const r = map(i, 0, num-1, r1, r2);
		drawNEdge(w2, h2, r, 13, da);
	}

	// // noLoop() removed for animation
}

function drawNEdge(xc, yc, r, n, da) {
	beginShape();
	for (let a = 0; a <= TAU; a += TAU/n) {
		const x = xc + cos(a+da) * r;
		const y = yc + sin(a+da) * r;
		vertex(x, y);
	}
	endShape();
}
